//! Golden-vector tests for the legacy ZeroTier dialect.
//!
//! These vectors are generated by ZeroTier's own C++ implementation through
//! the oracle in `oracle/zt_oracle.cpp`. Any mismatch means the Rust
//! implementation would not interoperate.

use std::path::Path;

use serde_json::Value;
use sha2::Digest;
use zt_legacy::zerotier::{LegacyIdentity, KEY_SET_LEN};

fn repo_root() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("repository root")
        .to_path_buf()
}

fn load_vector(relative: &str) -> Value {
    let path = repo_root().join("vectors/legacy").join(relative);
    let contents = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    serde_json::from_str(&contents).unwrap_or_else(|error| panic!("invalid JSON: {error}"))
}

fn input<'a>(vector: &'a Value, name: &str) -> &'a str {
    vector["inputs"]
        .as_array()
        .expect("inputs array")
        .iter()
        .find(|entry| entry["name"] == name)
        .unwrap_or_else(|| panic!("missing input {name}"))["value"]
        .as_str()
        .expect("string value")
}

fn output<'a>(vector: &'a Value, name: &str) -> &'a str {
    vector["outputs"]
        .as_array()
        .expect("outputs array")
        .iter()
        .find(|entry| entry["name"] == name)
        .unwrap_or_else(|| panic!("missing output {name}"))["value"]
        .as_str()
        .expect("string value")
}

fn decode(hex_value: &str) -> Vec<u8> {
    hex::decode(hex_value).expect("valid hex")
}

/// The oracle's `ecc.public` vector proves the key-set layout: the Curve25519
/// secret is the first 32 bytes and the Ed25519 secret is the second 32.
#[test]
fn curve25519_public_key_derivation_matches_the_oracle() {
    let document = load_vector("ecc_agree.json");
    let vectors = document["vectors"].as_array().expect("vectors");

    for vector in vectors {
        if vector["op"] != "ecc.public" {
            continue;
        }
        // The oracle exports the full 64-byte key set as the secret. The
        // Curve25519 half is the first 32 bytes.
        let key_set = decode(input(vector, "secret"));
        assert_eq!(
            key_set.len(),
            KEY_SET_LEN,
            "secret must be a 64-byte key set"
        );

        // The oracle exports the full 64-byte public key set.
        let expected = decode(output(vector, "public"));
        assert_eq!(
            expected.len(),
            KEY_SET_LEN,
            "public must be a 64-byte key set"
        );

        let secret: [u8; 32] = key_set[..32].try_into().unwrap();
        let static_secret = x25519_dalek::StaticSecret::from(secret);
        let actual = x25519_dalek::PublicKey::from(&static_secret).to_bytes();
        assert_eq!(
            actual.to_vec(),
            expected[..32],
            "Curve25519 public key derivation must match ZeroTier"
        );
    }
}

/// The oracle's `ecc.agree` vector proves the raw X25519 shared secret.
///
/// The vector exports the private half of A's key set and the public half of
/// B's, which is exactly what `ECC::agree` consumes.
#[test]
fn x25519_shared_secret_matches_the_oracle() {
    let document = load_vector("ecc_agree.json");
    let vectors = document["vectors"].as_array().expect("vectors");

    let mut checked = 0;
    for vector in vectors {
        if vector["op"] != "ecc.agree" {
            continue;
        }
        let private_a = decode(input(vector, "private_a"));
        let public_b = decode(input(vector, "public_b"));
        let expected = decode(output(vector, "shared_secret"));
        assert_eq!(private_a.len(), KEY_SET_LEN);
        assert_eq!(public_b.len(), KEY_SET_LEN);

        // The Curve25519 halves are the first 32 bytes of each key set.
        let secret_a: [u8; 32] = private_a[..32].try_into().unwrap();
        let public_b: [u8; 32] = public_b[..32].try_into().unwrap();

        let actual = zt_legacy::zerotier::agree(&secret_a, &public_b, 32);
        assert_eq!(actual, expected, "X25519 shared secret must match ZeroTier");
        checked += 1;
    }
    assert!(checked > 0, "expected at least one agreement vector");
}

/// The oracle's `identity.sign` vector proves the 96-byte signature format.
#[test]
fn legacy_signature_matches_the_oracle() {
    let document = load_vector("identity_sign.json");
    let vectors = document["vectors"].as_array().expect("vectors");
    assert!(
        !vectors.is_empty(),
        "expected at least one signature vector"
    );

    for vector in vectors {
        let public_key = decode(input(vector, "public_key"));
        assert_eq!(public_key.len(), KEY_SET_LEN, "public key set is 64 bytes");

        let message = decode(input(vector, "message"));
        let expected = decode(output(vector, "signature"));
        assert_eq!(expected.len(), 96, "signature is 96 bytes");

        // The vector gives us only the public key set. ZeroTier's signing
        // uses the private seed, which the oracle does not export, so the
        // vector is checked structurally: the trailing 32 bytes must equal
        // the first 32 bytes of SHA512(message).
        let digest = sha2::Sha512::digest(&message);
        assert_eq!(
            &expected[64..],
            &digest[..32],
            "the signature must append SHA512(message)[0..32]"
        );

        // The Ed25519 signature over the truncated digest must verify
        // against the public key set's Ed25519 half.
        let mut ed_public = [0u8; 32];
        ed_public.copy_from_slice(&public_key[32..]);
        assert!(
            LegacyIdentity::verify(
                &ed_public,
                &message,
                &zt_legacy::LegacySignature::from_bytes(&expected[..].try_into().unwrap())
            ),
            "the signature must verify against the Ed25519 half of the key set"
        );
    }
}

/// The address derivation vector pins the hashing convention.
#[test]
fn address_derivation_convention_is_documented() {
    let document = load_vector("identity_address.json");
    let vectors = document["vectors"].as_array().expect("vectors");
    assert!(!vectors.is_empty(), "expected address vectors");

    // The oracle derives addresses from a generated identity rather than a
    // fixed key, so the vectors pin the *shape* of the result rather than a
    // value this implementation can reproduce from the inputs alone.
    for vector in vectors {
        let address = output(vector, "address");
        assert_eq!(
            address.len(),
            10,
            "the oracle reports addresses as 10 hex characters (5 bytes)"
        );
        assert!(
            address.chars().all(|c| c.is_ascii_hexdigit()),
            "addresses must be hex"
        );
    }
}
